7	impl RenderContext {
8	    /// Creates a new [`RenderContext`] for testing.
9	    pub fn new_test() -> Self {
10	        let instance = wgpu::Instance::new(config::testing_instance_descriptor());
11	        let adapter = config::select_testing_adapter(&instance);
12	        let device_caps = config::DeviceCaps::from_adapter(&adapter)
13	            .expect("Failed to determine device capabilities");
14	        let (device, queue) =
15	            pollster::block_on(adapter.request_device(&device_caps.device_descriptor(), None))
16	                .expect("Failed to request device.");
17	
18	        Self::new(
19	            &adapter,
20	            Arc::new(device),
21	            Arc::new(queue),
22	            wgpu::TextureFormat::Rgba8Unorm,
23	        )
24	        .expect("Failed to create RenderContext")
25	    }
26	
27	    /// Executes a test frame.
28	    ///
29	    /// Note that this "executes" a frame in thus far that it doesn't necessarily draw anything,
30	    /// depending on what the callback does.
31	    pub fn execute_test_frame<I>(&mut self, create_gpu_work: impl FnOnce(&mut Self) -> I)
32	    where
33	        I: IntoIterator<Item = wgpu::CommandBuffer>,
34	    {
35	        self.begin_frame();
36	        let command_buffers = create_gpu_work(self);
37	        self.before_submit();
38	        self.queue.submit(command_buffers);
39	
40	        // Wait for all GPU work to finish.
41	        self.device.poll(wgpu::Maintain::Wait);
42	
43	        // Start a new frame in order to handle the previous' frame errors.
44	        self.begin_frame();
45	    }
46	}
