3	/// Tries downcasting a given value into the specified possibilities (or all of them
4	/// if none are specified), then run the given expression on the downcasted value.
5	///
6	/// E.g. to `dbg!()` the downcasted value on a wgpu error:
7	/// ```ignore
8	/// try_downcast!(my_error => |inner| { dbg!(inner); })
9	/// ```
10	macro_rules! try_downcast {
11	    ($value:expr => |$binding:pat_param| $do:expr => [$ty:ty, $($tail:ty $(,)*),*]) => {
12	        try_downcast!($value => |$binding| $do => $ty);
13	        try_downcast!($value => |$binding| $do => [$($tail),*]);
14	    };
15	    ($value:expr => |$binding:pat_param| $do:expr => [$ty:ty $(,)*]) => {
16	        try_downcast!($value => |$binding| $do => $ty);
17	    };
18	    ($value:expr => |$binding:pat_param| $do:expr => $ty:ty) => {
19	        if let Some($binding) = ($value).downcast_ref::<$ty>() {
20	            break Some({ $do });
21	        }
22	    };
23	    ($value:expr => |$binding:pat_param| $do:expr) => {
24	        loop {
25	            try_downcast![$value => |$binding| $do => [
26	                wgpu_core::command::ClearError,
27	                wgpu_core::command::CommandEncoderError,
28	                wgpu_core::command::ComputePassError,
29	                wgpu_core::command::CopyError,
30	                wgpu_core::command::DispatchError,
31	                wgpu_core::command::DrawError,
32	                wgpu_core::command::ExecutionError,
33	                wgpu_core::command::PassErrorScope,
34	                wgpu_core::command::QueryError,
35	                wgpu_core::command::QueryUseError,
36	                wgpu_core::command::RenderBundleError,
37	                wgpu_core::command::RenderCommandError,
38	                wgpu_core::command::RenderPassError,
39	                wgpu_core::command::ResolveError,
40	                wgpu_core::command::TransferError,
41	                wgpu_core::binding_model::BindError,
42	                wgpu_core::binding_model::BindingTypeMaxCountError,
43	                wgpu_core::binding_model::CreateBindGroupError,
44	                wgpu_core::binding_model::CreatePipelineLayoutError,
45	                wgpu_core::binding_model::GetBindGroupLayoutError,
46	                wgpu_core::binding_model::PushConstantUploadError,
47	                wgpu_core::device::DeviceError,
48	                wgpu_core::device::RenderPassCompatibilityError,
49	                wgpu_core::pipeline::ColorStateError,
