128	// Custom deduplication for shader compilation errors, based on compiler message.
129	impl DedupableError for wgpu_core::pipeline::CreateShaderModuleError {
130	    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
131	        type_of_var(self).hash(state);
132	        #[allow(clippy::enum_glob_use)]
133	        use wgpu_core::pipeline::CreateShaderModuleError::*;
134	        match self {
135	            Parsing(err) => err.source.hash(state),
136	            Validation(err) => err.source.hash(state),
137	            _ => {}
138	        }
139	    }
140	
141	    fn eq(&self, rhs: &(dyn std::error::Error + Send + Sync + 'static)) -> bool {
142	        if rhs.downcast_ref::<Self>().is_none() {
143	            return false;
144	        }
145	        let rhs = rhs.downcast_ref::<Self>().unwrap();
146	
147	        #[allow(clippy::enum_glob_use)]
148	        use wgpu_core::pipeline::CreateShaderModuleError::*;
149	        match (self, rhs) {
150	            (Parsing(err1), Parsing(err2)) => err1.source == err2.source,
151	            (Validation(err1), Validation(err2)) => err1.source == err2.source,
152	            _ => true,
153	        }
154	    }
155	}
